fn linear(cs:&[u64])->P{let mut p=P::new();for j in 0..cs.len(){let mut e=[0;4];e[j]=1;term(&mut p,e,cs[j]);}p.retain(|_,v|*v!=0);p}
fn scaled(p:&P,a:u64)->P{p.iter().filter_map(|(e,&x)|{let v=mul(x,a);(v!=0).then_some((*e,v))}).collect()}
fn psum(a:&P,b:&P)->P{let mut p=a.clone();for(e,&x)in b{term(&mut p,*e,x)}p.retain(|_,x|*x!=0);p}
fn standard(cs:&[u64;6])->P{let f=cs;let a=P::from([([0,2,0,0],1),([1,0,1,0],Q-4)]);let b=P::from([([3,0,0,0],sub(0,mul(4,f[0]))),([2,1,0,0],sub(0,mul(2,f[1]))),([2,0,1,0],sub(0,mul(4,f[2]))),([1,1,1,0],sub(0,mul(2,f[3]))),([1,0,2,0],sub(0,mul(4,f[4]))),([0,1,2,0],sub(0,mul(2,f[5])))]);
 let c=P::from([([4,0,0,0],sub(mul(f[1],f[1]),mul(4,mul(f[0],f[2])))),([3,1,0,0],sub(0,mul(4,mul(f[0],f[3])))),([3,0,1,0],sub(0,mul(2,mul(f[1],f[3])))),([2,2,0,0],sub(0,mul(4,mul(f[0],f[4])))),([2,1,1,0],sub(mul(4,mul(f[0],f[5])),mul(4,mul(f[1],f[4])))),([2,0,2,0],add(sub(mul(2,mul(f[1],f[5])),mul(4,mul(f[2],f[4]))),mul(f[3],f[3]))),([1,3,0,0],sub(0,mul(4,mul(f[0],f[5])))),([1,2,1,0],sub(0,mul(4,mul(f[1],f[5])))),([1,1,2,0],sub(0,mul(4,mul(f[2],f[5])))),([1,0,3,0],sub(0,mul(2,mul(f[3],f[5])))),([0,0,4,0],mul(f[5],f[5]))]);
 let h=linear(&[0,0,0,1]);psum(&psum(&product(&a,&product(&h,&h)),&product(&b,&h)),&c)}
fn main(){counted::disable();assert!(include_str!("../curve-recovery/CONTROL.txt").contains("coefficients=[209, 127, 378, 47, 539, 495]"));let coeff:Vec<u64>=include_str!("../image-quartic/CONTROL.txt").lines().find(|l|l.starts_with("TARGET_QUARTIC\t")).unwrap().split('\t').nth(1).unwrap().split(',').map(|s|s.parse().unwrap()).collect();let target:P=monomials(4).into_iter().zip(coeff).filter(|(_,v)|*v!=0).collect();let atnode=node_transform(&target,[1,284,243,459]);let a:P=atnode.iter().filter(|(e,_)|e[3]==2).map(|(e,&v)|{let mut e=*e;e[3]=0;(e,v)}).collect();
 let p=[1,154,322,0];let u=[0,380,576,0];let v=[0,1,0,0];let dirs:[P;4]=std::array::from_fn(|j|P::from([([1,0,0,0],u[j]),([0,1,0,0],v[j])]));let ad=substitute(&a,&dirs);let lv=bilinear(&a,p,v);assert_eq!(bilinear(&a,p,u),0);let lp=P::from([([0,1,0,0],lv)]);let param:[P;4]=std::array::from_fn(|j|psum(&scaled(&ad,p[j]),&scaled(&product(&lp,&dirs[j]),Q-1)));
 let basis=[[0,2,0,0],[1,1,0,0],[2,0,0,0]];let m:Vec<Vec<u64>>=(0..3).map(|i|basis.iter().map(|e|*param[i].get(e).unwrap_or(&0)).collect()).collect();let aug:Vec<_>=(0..3).map(|i|m[i].iter().copied().chain((0..3).map(|j|(i==j)as u64)).collect()).collect();let(inv,piv)=rref(aug);assert_eq!(piv,vec![0,1,2]);let inv:Vec<Vec<u64>>=inv.iter().map(|r|r[3..].to_vec()).collect();
 let vars:[P;4]=std::array::from_fn(|i|if i<3{linear(&[m[i][0],mul(m[i][1],pow(2,Q-2)),m[i][2]])}else{linear(&[0,0,0,1])});let f=substitute(&atnode,&vars);let acon:P=f.iter().filter(|(e,_)|e[3]==2).map(|(e,&v)|{let mut e=*e;e[3]=0;(e,v)}).collect();let ast=P::from([([0,2,0,0],1),([1,0,1,0],Q-4)]);let alpha=*acon.get(&[0,2,0,0]).unwrap();assert_ne!(alpha,0);assert_eq!(acon,scaled(&ast,alpha));let bold:P=f.iter().filter(|(e,_)|e[3]==1).map(|(e,&v)|{let mut e=*e;e[3]=0;(e,v)}).collect();let cs=[209,127,378,47,539,495];let std=standard(&cs);let bstd:P=std.iter().filter(|(e,_)|e[3]==1).map(|(e,&v)|{let mut e=*e;e[3]=0;(e,v)}).collect();let ratio=Q-28;let lambda=mul(ratio,alpha);let mu=mul(mul(ratio,ratio),alpha);let diff=psum(&scaled(&bold,ratio),&scaled(&bstd,Q-1));let lnum=linear(&[*diff.get(&[1,2,0,0]).unwrap_or(&0),*diff.get(&[0,3,0,0]).unwrap_or(&0),*diff.get(&[0,2,1,0]).unwrap_or(&0)]);assert_eq!(product(&ast,&lnum),diff);let l=scaled(&lnum,pow(2,Q-2));let hh=psum(&l,&linear(&[0,0,0,lambda]));let varsstd=[linear(&[1,0,0]),linear(&[0,1,0]),linear(&[0,0,1]),hh];assert_eq!(substitute(&std,&varsstd),scaled(&f,mu));
 let local:Vec<Vec<u64>>=(0..3).map(|i|inv[i].iter().map(|&x|mul(x,if i==1{2}else{1})).collect()).collect();let node=[284,243,459];let mut gl=vec![vec![0;4];4];for i in 0..3{for j in 0..3{gl[i][j+1]=local[i][j];gl[i][0]=sub(gl[i][0],mul(local[i][j],node[j]));}}gl[3][0]=lambda;for i in 0..3{let mut e=[0;4];e[i]=1;let x=*l.get(&e).unwrap_or(&0);for j in 0..4{gl[3][j]=add(gl[3][j],mul(x,gl[i][j]));}}assert_eq!(rref(gl.clone()).0.len(),4);let glvars: [P;4]=std::array::from_fn(|i|linear(&gl[i]));let identity=substitute(&std,&glvars);let factor=mul(*identity.values().next().unwrap(),pow(*target.get(identity.keys().next().unwrap()).unwrap(),Q-2));assert_eq!(identity,scaled(&target,factor));for(i,row)in gl.iter().enumerate(){println!("GL\t{i}\t{}",row.iter().map(u64::to_string).collect::<Vec<_>>().join(","));}
 println!("alpha={alpha} lambda={lambda} proportionality={factor} exact_full_quartic_identity=true independent_verification=false");
 let rows:Vec<Vec<u64>>=include_str!("../quintic-map/CONTROL.txt").lines().filter(|l|l.starts_with("MAP\t")).map(|l|l.split('\t').nth(2).unwrap().split(',').map(|s|s.parse().unwrap()).collect()).collect();let newrows:Vec<Vec<u64>>=gl.iter().map(|r|(0..56).map(|j|(0..4).fold(0,|s,i|add(s,mul(r[i],rows[i][j])))).collect()).collect();for(i,row)in newrows.iter().enumerate(){println!("STANDARD_MAP\t{i}\t{}",row.iter().map(u64::to_string).collect::<Vec<_>>().join(","));}
}
